// Base64 encoded images for better performance
// Generated automatically by scripts/generateBase64.cjs
// Last updated: 2025-09-14T17:17:08.832Z

export const base64Images = {
  // Logo de la aplicación
  logoApp: 'data:image/png;base64,',

  // Emoji de hueso para moneda
  emojiHueso: 'data:image/png;base64,',

} as const;

// Función helper para crear URLs de datos desde base64
export function createDataUrl(base64: string, mimeType: string = 'image/png'): string {
  if (base64.startsWith('data:')) {
    return base64;
  }
  return `data:${mimeType};base64,${base64}`;
}

// Función para obtener imagen optimizada (base64 si está disponible, sino URL normal)
export function getOptimizedImage(imageName: keyof typeof base64Images, fallbackPath: string): string {
  const base64Data = base64Images[imageName];
  
  // Si la imagen base64 está vacía, usar el path normal
  if (!base64Data || base64Data === 'data:image/png;base64,' || base64Data === '') {
    return fallbackPath;
  }
  
  return base64Data;
}

// Función para precargar imágenes críticas (las que no están en base64)
export function preloadCriticalImages(): void {
  const criticalImages = [
    '/images/Heart.png',
    '/images/huesitos.png',
    '/images/Tienda.png',
    '/images/emoji llama.png',
    '/images/Descarte.png',
    '/images/Duplicar.png',
    '/images/Adrenalina.png',
    '/images/Inmunidad.png',
    '/images/Saltar.png',
  ];

  criticalImages.forEach(src => {
    const img = new Image();
    img.src = src;
  });
}
